-- Spots taken count only people still holding a place.
begin;
select plan(3);

insert into public.people (id, first_name, last_name) values
  ('11000000-0000-4000-8000-000000000001', 'A', 'One'),
  ('11000000-0000-4000-8000-000000000002', 'B', 'Two'),
  ('11000000-0000-4000-8000-000000000003', 'C', 'Three');
insert into public.volunteer_parties (id, event_id, registrant_person_id)
values ('21000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '11000000-0000-4000-8000-000000000001');
insert into public.volunteer_registrations (id, party_id, event_id, person_id, status) values
  ('31000000-0000-4000-8000-000000000001', '21000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '11000000-0000-4000-8000-000000000001', 'confirmed'),
  ('31000000-0000-4000-8000-000000000002', '21000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '11000000-0000-4000-8000-000000000002', 'incomplete'),
  ('31000000-0000-4000-8000-000000000003', '21000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '11000000-0000-4000-8000-000000000003', 'cancelled');
insert into public.registration_shifts (registration_id, shift_id, event_id) values
  ('31000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000021', '00000000-0000-4000-8000-000000000002'),
  ('31000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000021', '00000000-0000-4000-8000-000000000002'),
  ('31000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000021', '00000000-0000-4000-8000-000000000002'),
  ('31000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000022', '00000000-0000-4000-8000-000000000002');

select results_eq(
  $$ select shift_id, taken from public.shift_spots_taken(array['00000000-0000-4000-8000-000000000002'::uuid]) order by shift_id $$,
  $$ values ('00000000-0000-4000-8000-000000000021'::uuid, 2), ('00000000-0000-4000-8000-000000000022'::uuid, 1) $$,
  'active registrations hold a place; cancelled ones free it'
);
select is_empty(
  $$ select * from public.shift_spots_taken(array['00000000-0000-4000-8000-000000000003'::uuid]) $$,
  'other events are not counted'
);
select ok(
  not has_function_privilege('anon', 'public.shift_spots_taken(uuid[])', 'execute'),
  'anon cannot call it'
);

select * from finish();
rollback;
